UPDATE proposal_templates
SET blocks = jsonb_set(
  blocks,
  '{2,html}',
  to_jsonb('<div style="box-sizing:border-box;width:760px;max-width:760px;min-height:500px;margin:0 auto;padding:42px 46px;border-radius:18px;overflow:hidden;display:flex;flex-direction:column;justify-content:center;font-family:Inter,system-ui,sans-serif;background:linear-gradient(135deg,#0f172a 0%,#064e3b 100%);color:#ffffff;position:relative;"><div style="display:inline-flex;align-items:center;gap:6px;background:#22c55e;color:#fff;padding:6px 14px;border-radius:999px;font-size:11px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;margin-bottom:14px;width:max-content;"><span style="width:6px;height:6px;border-radius:50%;background:#fff;opacity:.9;"></span>Produto</div><h2 style="font-size:32px;margin:0 0 12px;font-weight:800;letter-spacing:-.02em;line-height:1.1;">Sobre o <span style="color:#4ade80;">i-Ganhei</span></h2><p style="font-size:14px;line-height:1.6;margin:0 0 12px;color:#cbd5e1;max-width:680px;">O <strong style="color:#fff;">i-Ganhei</strong> é a solução da StartGi desenvolvida para apoiar empresas na gestão estratégica de vendas públicas, conectando informações, processos e acompanhamento operacional em uma estrutura mais organizada, inteligente e orientada à tomada de decisão.</p><p style="font-size:14px;line-height:1.6;margin:0 0 20px;color:#cbd5e1;max-width:680px;">A solução foi concebida para apoiar empresas que buscam ampliar controle operacional, capacidade de acompanhamento e eficiência na condução da operação comercial junto ao mercado público.</p><div style="display:grid;grid-template-columns:repeat(3,1fr);gap:12px;"><div style="background:linear-gradient(160deg,#1e293b 0%,#0f172a 100%);padding:18px;border-radius:14px;border:1px solid #1e3a2e;position:relative;overflow:hidden;"><div style="width:38px;height:38px;border-radius:10px;background:#22c55e22;display:flex;align-items:center;justify-content:center;margin-bottom:12px;"><svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="#4ade80" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"/><circle cx="12" cy="12" r="6"/><circle cx="12" cy="12" r="2"/></svg></div><div style="color:#4ade80;font-size:11px;font-weight:700;letter-spacing:.12em;text-transform:uppercase;margin-bottom:6px;">Captação</div><div style="font-size:13px;line-height:1.5;color:#cbd5e1;">Monitoramento de portais públicos 24/7 com alertas em tempo real.</div></div><div style="background:linear-gradient(160deg,#1e293b 0%,#0f172a 100%);padding:18px;border-radius:14px;border:1px solid #1e3a2e;position:relative;overflow:hidden;"><div style="width:38px;height:38px;border-radius:10px;background:#22c55e22;display:flex;align-items:center;justify-content:center;margin-bottom:12px;"><svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="#4ade80" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><polygon points="22 3 2 3 10 12.46 10 19 14 21 14 12.46 22 3"/></svg></div><div style="color:#4ade80;font-size:11px;font-weight:700;letter-spacing:.12em;text-transform:uppercase;margin-bottom:6px;">Qualificação</div><div style="font-size:13px;line-height:1.5;color:#cbd5e1;">Filtros inteligentes por CNAE, objeto e região de atuação.</div></div><div style="background:linear-gradient(160deg,#1e293b 0%,#0f172a 100%);padding:18px;border-radius:14px;border:1px solid #1e3a2e;position:relative;overflow:hidden;"><div style="width:38px;height:38px;border-radius:10px;background:#22c55e22;display:flex;align-items:center;justify-content:center;margin-bottom:12px;"><svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="#4ade80" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><path d="M10 6.5h4M17.5 10v4M14 17.5h-4M6.5 14v-4"/></svg></div><div style="color:#4ade80;font-size:11px;font-weight:700;letter-spacing:.12em;text-transform:uppercase;margin-bottom:6px;">Gestão</div><div style="font-size:13px;line-height:1.5;color:#cbd5e1;">Workflow completo do edital até a homologação.</div></div></div></div>'::text)
)
WHERE id='9ac64afe-2213-4ceb-89c0-1bad0b83df87';